def find_code_snippet(query):
    # Search through all files in the project directory
    for filename in os.listdir('.'):
        if filename.endswith('.py') and 'search_query' not in filename:
            with open(os.path.join('.', filename), 'r') as f:
                content = f.read()
                # Check if the content contains the search query
                if search_query in content:
                    return os.path.join(filename, 'code_snippet.txt')
    return None

# Example usage
query = "for i in range(10): print(i)"
code_snippet = find_code_snippet(query)
